function t(n){return n.filter(e=>e.status==="paid").reduce((e,a)=>e+a.amount,0)}function u(n){return n.filter(e=>e.status==="pending").reduce((e,a)=>e+a.amount,0)}function r(n){return n.filter(e=>e.status==="overdue").reduce((e,a)=>e+a.amount,0)}function s(n){return{paid:"Bezahlt",pending:"Ausstehend",overdue:"Überfällig"}[n]||n}function d(n){return{paid:"badge-success",pending:"badge-warning",overdue:"badge-danger"}[n]||"badge-info"}function c(n){return"€ "+n.toLocaleString("de-DE")}export{s as a,u as b,t as c,r as d,c as f,d as s};
